      formatting: ['expectedTotal'],
      ownership: ['foreignTotal'],
    },
  },
  {
    fileName: 'fr14-category-management.json',
    specName: 'fr14-category-management.spec.js',
    prefix: 'FR14',
    requiredByAction: {
